mapper.select:
SELECT 
FROM tb_business_key_provisioning
WHERE status = #{status}
  AND modify_time <= #{before}
  AND row_valid = 1
ORDER BY modify_time ASC
LIMIT #{limit}

SELECT 
FROM tb_business_key_provisioning t
WHERE t.row_valid = 1

    AND t.id = #{id}


    AND t.request_id = #{requestId}


    AND t.device_sn = #{deviceSn}


    AND t.business_domain = #{businessDomain}


    AND t.status = #{status}

ORDER BY t.id DESC

